[CmdletBinding()]
param()

$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest

$root=(Get-Location).Path
if(-not(Test-Path (Join-Path $root 'pubspec.yaml'))){
  throw 'Run this script from the project root.'
}

$stamp=Get-Date -Format 'yyyyMMdd_HHmmss'
$backup=Join-Path (Split-Path $root -Parent) "almustafa-connect-erp_backups\exam_component_passing_mode_complete_$stamp"

$files=@(
  'lib\features\exams\domain\entities\exam_subject_setup_entity.dart',
  'lib\features\exams\data\models\exam_subject_setup_model.dart',
  'lib\features\academic_structure\domain\services\subject_component_exam_service.dart',
  'lib\features\exams\presentation\pages\exam_form_page.dart',
  'lib\features\exams\domain\usecases\generate_exam_results.dart',
)

foreach($file in $files){
  $source=Join-Path $root $file
  if(-not(Test-Path $source)){throw "Required file not found: $file"}
  $destination=Join-Path $backup $file
  New-Item -ItemType Directory -Force -Path (Split-Path $destination -Parent)|Out-Null
  Copy-Item $source $destination -Force
}

$target = Join-Path $root 'lib\features\exams\domain\entities\exam_subject_setup_entity.dart'
New-Item -ItemType Directory -Force -Path (Split-Path $target -Parent) | Out-Null
[IO.File]::WriteAllBytes($target, [Convert]::FromBase64String(@'

'@))

$target = Join-Path $root 'lib\features\exams\data\models\exam_subject_setup_model.dart'
New-Item -ItemType Directory -Force -Path (Split-Path $target -Parent) | Out-Null
[IO.File]::WriteAllBytes($target, [Convert]::FromBase64String(@'

'@))

$target = Join-Path $root 'lib\features\academic_structure\domain\services\subject_component_exam_service.dart'
New-Item -ItemType Directory -Force -Path (Split-Path $target -Parent) | Out-Null
[IO.File]::WriteAllBytes($target, [Convert]::FromBase64String(@'

'@))

$target = Join-Path $root 'lib\features\exams\presentation\pages\exam_form_page.dart'
New-Item -ItemType Directory -Force -Path (Split-Path $target -Parent) | Out-Null
[IO.File]::WriteAllBytes($target, [Convert]::FromBase64String(@'

'@))

$target = Join-Path $root 'lib\features\exams\domain\usecases\generate_exam_results.dart'
New-Item -ItemType Directory -Force -Path (Split-Path $target -Parent) | Out-Null
[IO.File]::WriteAllBytes($target, [Convert]::FromBase64String(@'

'@))


dart format @($files)
if($LASTEXITCODE -ne 0){
  throw "FORMAT ERROR. Backup: $backup"
}

flutter analyze lib\features\exams lib\features\academic_structure lib\features\results --no-fatal-infos --no-fatal-warnings
if($LASTEXITCODE -ne 0){
  throw "ANALYZE ERROR. Backup: $backup"
}

Write-Host ''
Write-Host 'Exam component passing mode completed successfully.' -ForegroundColor Green
Write-Host 'Blank component Passing fields: combined parent subject passing rule.' -ForegroundColor Green
Write-Host 'All component Passing fields filled: every component must pass.' -ForegroundColor Green
Write-Host "Backup: $backup" -ForegroundColor Cyan
